    const start=()=>{clearInterval(timer);if(!paused)timer=setInterval(()=>show(index+1),10000);play.textContent=paused?'Play slideshow':'Pause slideshow';play.setAttribute('aria-pressed',String(paused));const motion=motions.get(heroSlides[index]);if(motion){if(paused)motion.pause();else motion.play();}};
