  document.addEventListener('click', e => { const button = e.target.closest('[data-gallery]'); if (!button) return; const card = button.closest('[data-collection]'); const img = $('[data-gallery-image]', card); const index = ((Number(card.dataset.view || 0) + Number(button.dataset.gallery)) + 3) % 3; card.dataset.view = String(index); const view = galleryViews[index]; img.style.transformOrigin = view.origin; img.style.transform = `scale(${view.scale})`; const collection = data.collections.find(c => c.id === card.dataset.collection); img.alt = `${collection.name} illustrative kitchen, ${view.title}`; $('.image-counter', card).textContent = `${index + 1} / 3 · ${index === 0 ? 'Room' : 'Detail'}`; });
