  function filterCatalog() { const style = $('#filter-style').value, color = $('#filter-color').value, material = $('#filter-material').value, saved = $('#filter-saved').value; let count = 0; $$('#catalog-grid [data-collection]').forEach(card => { const c = data.collections.find(x => x.id === card.dataset.collection); const match = (!style || c.style === style) && (!color || c.color === color) && (!material || c.material === material) && (!saved || favorites.includes(c.id)); card.hidden = !match; if (match) count++; }); $('#result-count').textContent = `${count} collection${count !== 1 ? 's' : ''}${[style,color,material].filter(Boolean).length ? ' · '+[style,color,material].filter(Boolean).join(' / ') : ''}`; let empty = $('#catalog-empty'); if (!empty) { empty = document.createElement('div'); empty.id = 'catalog-empty'; empty.className = 'empty'; empty.innerHTML = '<h3>No collections match those choices.</h3><p>Try clearing a filter, or save a collection to find it here.</p><button class="btn outline" id="empty-clear">Clear filters</button>'; $('#catalog-grid').append(empty); $('#empty-clear').addEventListener('click', () => $('#clear-filters').click()); } empty.hidden = count !== 0; const url = new URL(location.href); for (const key of ['style','color','material','saved']) { const value = $(`#filter-${key}`).value; if (value) url.searchParams.set(key,value); else url.searchParams.delete(key); } history.replaceState(null,'',url.pathname+url.search); }
  if ($('#catalog-grid')) { const params = new URLSearchParams(location.search); for (const key of ['style','color','material','saved']) { const el = $(`#filter-${key}`); if ([...el.options].some(o => o.value === params.get(key))) el.value = params.get(key); el.addEventListener('change', filterCatalog); } $('#clear-filters').addEventListener('click', () => { $$('.filters select').forEach(s => s.value = ''); filterCatalog(); }); filterCatalog(); }
