  const blankPlan=()=>({flowVersion:3,intent:'',timeline:'',budget:'',showPresets:false,type:'Homeowner',location:'',units:'',layout:'',collection:'',scope:'',notes:'',help:'',material:'',color:'',profile:'',accessories:[],cabinets:[],baseWidths:{},storage:[],step:0});
