  function selectedRows(){const c=data.collections.find(c=>c.id===plan.collection);return [
 ['Kitchen size',plan.layout,0],['Location',plan.location,0],['Cabinets',plan.cabinets.length?plan.cabinets.reduce((n,c)=>n+c.qty,0)+' cabinets':'',1],['Accessories',plan.accessories.join(', '),0],['Handles & knobs',plan.hardwareStyle?(plan.hardwareStyle+(plan.hardwareFinish?' · '+plan.hardwareFinish:'')):'',0],
 ['Collection',c?.name||(plan.collection==='undecided'?'Designer recommendation':''),1],['Door style',plan.profile,1],['Material',plan.material,1],['Color',plan.color,1],['Finish',plan.finish,1],['Support',plan.help,2],['Installation',plan.scope,2],['Notes',plan.notes,0]
 ].filter(([,value])=>String(value||'').trim());}
  function summaryContent(){const rows=selectedRows();if(!rows.length)return '<p class="summary-empty">Your choices will appear here as you build your request.</p>';return [0,1,2].map(step=>{const group=rows.filter(row=>row[2]===step);return group.length?'<div class="selection-group"><dt class="selection-group-title">'+['Kitchen & accessories','Look & finishes','Support'][step]+'</dt>'+group.map(([label,value])=>'<div class="selection-row"><dt>'+label+'</dt><dd><button type="button" class="summary-choice-link" data-summary-step="'+step+'" data-summary-category="'+label+'" aria-label="Change '+label.toLowerCase()+'">'+escape(value)+'<span aria-hidden="true"> ↗</span></button></dd></div>').join('')+'</div>':'';}).join('');}
